    "id": "ald-mcq-062",
    "questionNumber": 62,
    "question": "Q62. When benzaldehyde is heated with concentrated aqueous potassium hydroxide ($50\\% \\text{ KOH}$), it undergoes the Cannizzaro reaction to form:",
    "options": {
      "A": "Benzoic acid and Potassium hydride",
      "B": "Benzyl alcohol and Potassium benzoate",
      "C": "Cinnamic acid and Benzyl alcohol",
      "D": "Benzophenone and Methanol"
    },
    "optionsList": [
      "Benzoic acid and Potassium hydride",
      "Benzyl alcohol and Potassium benzoate",
      "Cinnamic acid and Benzyl alcohol",
      "Benzophenone and Methanol"
    ],
    "correctAnswer": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT & PRINCIPLE:\nCannizzaro reaction: base-induced disproportionation of aldehydes lacking alpha-hydrogens.\n\n2. GIVEN INFORMATION / DATA:\nBenzaldehyde ($C_6H_5CHO$) with $50\\% KOH$ under heating.\n\n3. FORMULA / EQUATION:\n$2C_6H_5CHO + KOH \\rightarrow C_6H_5CH_2OH + C_6H_5COOK$\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Aldehydes lacking alpha-hydrogen atoms (such as benzaldehyde, formaldehyde, and trimethylacetaldehyde) cannot form an enolate ion required for aldol condensation.\n2. In the presence of concentrated alkali, nucleophilic addition of $OH^-$ produces a tetrahedral dianion intermediate.\n3. Hydride ion ($H^-$) is directly transferred from this intermediate to a second molecule of benzaldehyde (rate-determining step).\n4. This results in self-oxidation-reduction (disproportionation): one molecule of benzaldehyde is reduced to benzyl alcohol ($C_6H_5CH_2OH$), while the other is oxidized to benzoate salt ($C_6H_5COOK$).\n\n5. FINAL CONCLUSION:\nBenzyl alcohol and Potassium benzoate\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nBenzaldehyde cannot form cinnamic acid without acetic anhydride (Perkin reaction); free benzoic acid precipitates only upon acidification.",
    "solutionStructured": {
      "concept": "Cannizzaro reaction: base-induced disproportionation of aldehydes lacking alpha-hydrogens.",
      "given": "Benzaldehyde ($C_6H_5CHO$) with $50\\% KOH$ under heating.",
      "formula": "$2C_6H_5CHO + KOH \\rightarrow C_6H_5CH_2OH + C_6H_5COOK$",
      "stepByStep": "1. Aldehydes lacking alpha-hydrogen atoms (such as benzaldehyde, formaldehyde, and trimethylacetaldehyde) cannot form an enolate ion required for aldol condensation.\n2. In the presence of concentrated alkali, nucleophilic addition of $OH^-$ produces a tetrahedral dianion intermediate.\n3. Hydride ion ($H^-$) is directly transferred from this intermediate to a second molecule of benzaldehyde (rate-determining step).\n4. This results in self-oxidation-reduction (disproportionation): one molecule of benzaldehyde is reduced to benzyl alcohol ($C_6H_5CH_2OH$), while the other is oxidized to benzoate salt ($C_6H_5COOK$).",
      "finalAnswer": "Benzyl alcohol and Potassium benzoate",
      "whyOtherOptionsWrong": "Benzaldehyde cannot form cinnamic acid without acetic anhydride (Perkin reaction); free benzoic acid precipitates only upon acidification."
    },
