    "question": "Q105. In the Hell-Volhard-Zelinsky (HVZ) reaction, carboxylic acids having an $\\alpha$-hydrogen react with chlorine or bromine in the presence of red phosphorus to yield:",
    "options": {
      "A": "$\\alpha$-Halocarboxylic acids",
      "B": "Acid chlorides",
      "C": "$\beta$-Halocarboxylic acids",
      "D": "Alkanes"
    },
